-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        mercaro_record_id,
        mercaro_customer_id,
        loyalty_id,
        email,
        full_name,
        city,
        buyer_segment,
        customer_status,
        as_of_date,
        violation_00,
        violation_01
    from {{ ref("ecommerce__mercaro_customer_extract__checked") }}
),
violations as (
    select
        'mercaro_record_id_not_null' as rule_name,
        mercaro_record_id,
        mercaro_customer_id,
        loyalty_id,
        email,
        full_name,
        city,
        buyer_segment,
        customer_status,
        as_of_date
    from quarantined
    where violation_00

    union all

    select
        'mercaro_record_id_unique' as rule_name,
        mercaro_record_id,
        mercaro_customer_id,
        loyalty_id,
        email,
        full_name,
        city,
        buyer_segment,
        customer_status,
        as_of_date
    from quarantined
    where violation_01
)

select
    rule_name,
    mercaro_record_id,
    mercaro_customer_id,
    loyalty_id,
    email,
    full_name,
    city,
    buyer_segment,
    customer_status,
    as_of_date
from violations
